1	use anyhow::Result;
2	use rand::rngs::StdRng;
3	
4	use super::ActiveRequestState;
5	use super::PendingRequest;
6	use crate::executor::DecodePlan;
7	use crate::executor::DecodeResult;
8	use crate::executor::DecodeStepItem;
9	use crate::executor::ModelExecutor;
10	use crate::executor::PrefillPlan;
11	use crate::executor::PrefillResult;
12	use crate::executor::PrefillStepItem;
13	use crate::executor::UnifiedPlan;
14	use crate::executor::UnifiedResult;
15	use crate::speculative::DraftPlan;
16	use crate::speculative::DraftRequestResult;
17	use crate::speculative::DraftStepItem;
18	use crate::speculative::VerifyPlan;
19	use crate::speculative::VerifyResult;
20	use crate::speculative::VerifyStepItem;
21	
22	pub(crate) enum ExecutionPlan {
23	    Prefill {
24	        pending: Vec<PendingRequest>,
25	    },
26	    Decode,
27	    /// Draft + verify the whole active batch (all requests are draft-ready).
28	    SpeculativeDecode,
29	    /// Verify the whole active batch over a one-token span — the load gate
30	    /// turned speculation off for this step. No draft is proposed, so the
31	    /// target commits one token per request, but the DFlash capture and the
32	    /// draft-ready state survive: the next round under the threshold
33	    /// speculates again. A plain decode would drop the capture, which only a
34	    /// fresh prefill rebuilds.
35	    GatedSpeculativeDecode,
36	    Unified {
37	        pending: Vec<PendingRequest>,
38	    },
39	}
40	
41	pub(crate) enum ExecutionArtifacts {
42	    Prefill {
43	        pending: Vec<PendingRequest>,
44	        result: PrefillResult,
45	    },
46	    Decode {
47	        result: DecodeResult,
48	    },
49	    SpeculativeDecode {
50	        verify: VerifyResult,
51	    },
52	    Unified {
53	        pending: Vec<PendingRequest>,
54	        result: UnifiedResult,
55	    },
56	}
57	
58	pub(crate) fn build_next_plan(
59	    have_active: bool,
60	    pending: Vec<PendingRequest>,
61	    speculative: bool,
62	) -> Option<ExecutionPlan> {
63	    // Prompt-logprobs requests need all-position logits, which the unified
64	    // forward does not compute (it passes all_position_logits=None). And under
65	    // DFlash speculation, an eligible request must capture its target hidden
66	    // context during prefill — the unified forward skips that capture, so a
67	    // request prefilled via Unified would never become draft-ready and DFlash
68	    // would silently no-op for it forever. Either way, route pending through a
69	    // dedicated prefill step instead of degrading silently.
70	    let needs_prompt_logprobs = pending.iter().any(|req| req.prompt_logprobs.is_some());
71	    // Deliberately a loose superset of the real capture eligibility
72	    // (`prefill_capture_supported`, which also needs `cached_tokens == 0 && no
73	    // prompt logprobs`): over-routing an ineligible request to a dedicated
74	    // prefill only costs one fusion, but under-routing a capture-eligible one
75	    // into Unified would silently break its readiness. Never tighten this into
76	    // the dangerous direction.
77	    let needs_dflash_capture = speculative
78	        && pending
79	            .iter()
80	            .any(|r| r.lora_adapter.is_none() && r.logprobs.is_none());
81	    if !pending.is_empty() && have_active && !needs_prompt_logprobs && !needs_dflash_capture {
82	        Some(ExecutionPlan::Unified { pending })
83	    } else if !pending.is_empty() {
84	        Some(ExecutionPlan::Prefill { pending })
85	    } else if have_active {
86	        Some(ExecutionPlan::Decode)
87	    } else {
88	        None
89	    }
90	}
91	
92	pub(crate) fn execute_plan(
93	    executor: &mut impl ModelExecutor,
94	    active: &mut [ActiveRequestState],
95	    plan: ExecutionPlan,
96	    rng: &mut StdRng,
97	) -> Result<ExecutionArtifacts> {
98	    match plan {
99	        ExecutionPlan::Prefill { pending } => {
100	            let indices: Vec<usize> = (0..pending.len()).collect();
101	            let requests = build_prefill_items(&pending, &indices);
102	            let mut result = executor.execute_prefill(PrefillPlan {
103	                requests: &requests,
104	                sample_seed: rand::RngExt::random(rng),
105	            })?;
106	            sort_prefill_results(&mut result.requests);
107	            Ok(ExecutionArtifacts::Prefill { pending, result })
108	        }
109	        ExecutionPlan::Decode => {
110	            let indices: Vec<usize> = (0..active.len()).collect();
111	            let requests = build_decode_items(active, &indices);
112	            let mut result = executor.execute_decode(DecodePlan {
113	                requests: &requests,
114	                sample_seed: rand::RngExt::random(rng),
115	            })?;
116	            sort_decode_results(&mut result.requests);
117	            Ok(ExecutionArtifacts::Decode { result })
118	        }
119	        ExecutionPlan::SpeculativeDecode => {
120	            // Two executor calls per step: draft proposes K tokens per request,
121	            // then a single target forward verifies the K+1 span. Both index by
122	            // request_id; sorting keeps draft and verify results aligned.
123	            let draft_requests = build_speculative_draft_items(active);
124	            let mut draft = executor.execute_speculative_draft(DraftPlan {
125	                requests: &draft_requests,
126	            })?;
127	            draft.requests.sort_by_key(|result| result.request_id);
128	            let verify_requests = build_speculative_verify_items(active, &draft.requests);
129	            let mut verify = executor.execute_speculative_verify(VerifyPlan {
130	                requests: &verify_requests,
131	                sample_seed: rand::RngExt::random(rng),
132	                gated: false,
133	            })?;
134	            verify.requests.sort_by_key(|result| result.request_id);
135	            Ok(ExecutionArtifacts::SpeculativeDecode { verify })
136	        }
137	        ExecutionPlan::GatedSpeculativeDecode => {
138	            let verify_requests = build_gated_verify_items(active);
139	            let mut verify = executor.execute_speculative_verify(VerifyPlan {
140	                requests: &verify_requests,
141	                sample_seed: rand::RngExt::random(rng),
142	                gated: true,
143	            })?;
144	            verify.requests.sort_by_key(|result| result.request_id);
145	            Ok(ExecutionArtifacts::SpeculativeDecode { verify })
146	        }
147	        ExecutionPlan::Unified { pending } => {
148	            let pending_indices: Vec<usize> = (0..pending.len()).collect();
149	            let active_indices: Vec<usize> = (0..active.len()).collect();
150	            let prefill_requests = build_prefill_items(&pending, &pending_indices);
151	            let decode_requests = build_decode_items(active, &active_indices);
152	            let mut result = executor.execute_unified(UnifiedPlan {
153	                prefill_requests: &prefill_requests,
154	                decode_requests: &decode_requests,
155	                sample_seed: rand::RngExt::random(rng),
156	            })?;
157	            sort_prefill_results(&mut result.prefill_requests);
158	            sort_decode_results(&mut result.decode_requests);
159	            Ok(ExecutionArtifacts::Unified { pending, result })
160	        }
161	    }
162	}
163	
164	/// `PEGAINFER_SPEC_MAX_BATCH=<n>` turns on the load-aware speculation gate: once
165	/// the active batch reaches `<n>` requests, the engine stops proposing drafts
166	/// for that step. `0`/unset = off. Read once; a malformed value refuses to
167	/// start (see [`crate::spec_env`]).
168	pub(crate) fn spec_max_batch() -> usize {
169	    static MAX_BATCH: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
170	    *MAX_BATCH.get_or_init(|| crate::spec_env::read(crate::spec_env::MAX_BATCH))
171	}
172	
173	/// What the engine does with the active batch this step.
174	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
175	pub(crate) enum SpeculationDecision {
176	    /// Every request is draft-ready and the batch is under the load gate:
177	    /// draft + verify.
178	    Speculate,
179	    /// Every request is draft-ready but the batch reached the load gate.
180	    Gated,
181	    /// Some request is not draft-ready, the batch is wider than the drafter
182	    /// serves, or no drafter is loaded: plain decode.
183	    NotReady,
184	}
185	
186	/// All-or-nothing: speculate the whole active batch only when every request is
187	/// draft-ready (no LoRA, no logprobs). A single non-ready request falls the
188	/// batch back to plain decode rather than running a mixed step. Sampling
189	/// params are NOT a gate: sampled-verify (#512) runs the regular sampler over
190	/// the verify rows, so the full surface — temperature/top_k/top_p/min_p/seed —
191	/// rides the speculative path.
192	pub(crate) fn speculation_decision_at(
193	    executor: &impl ModelExecutor,
194	    active: &[ActiveRequestState],
195	    max_batch: usize,
196	) -> SpeculationDecision {
197	    if !executor.speculative_enabled() || active.is_empty() {
198	        return SpeculationDecision::NotReady;
199	    }
200	    if executor
201	        .max_draft_batch()
202	        .is_some_and(|limit| active.len() > limit)
203	    {
204	        return SpeculationDecision::NotReady;
205	    }
206	    let all_ready = active.iter().all(|req| {
207	        executor.speculative_request_ready(req.request_id)
208	            && req.lora_adapter.is_none()
209	            && req.logprobs.is_none()
210	    });
211	    if !all_ready {
212	        return SpeculationDecision::NotReady;
213	    }
214	    if max_batch > 0 && active.len() >= max_batch {
215	        SpeculationDecision::Gated
216	    } else {
217	        SpeculationDecision::Speculate
218	    }
219	}
220	
221	fn build_speculative_draft_items(active: &[ActiveRequestState]) -> Vec<DraftStepItem> {
222	    active
223	        .iter()
224	        .map(|r| {
225	            // Only greedy requests may hedge; the draft lane turns the
226	            // remaining budget into eligibility against its effective branch
227	            // positions (a chain must survive the verify-side span clamp).
228	            let budget = if r.params.is_greedy() {
229	                r.max_tokens.saturating_sub(r.generated_count)
230	            } else {
231	                0
232	            };
233	            DraftStepItem::new(r.request_id, r.last_token, budget)
234	        })
235	        .collect()
236	}
237	
238	fn build_speculative_verify_items(
239	    active: &[ActiveRequestState],
240	    draft_results: &[DraftRequestResult],
241	) -> Vec<VerifyStepItem> {
242	    let mut requests = Vec::with_capacity(draft_results.len());
243	    for draft in draft_results {
244	        let active = active
245	            .iter()
246	            .find(|req| req.request_id == draft.request_id)
247	            .expect("draft request_id must exist in active set");
248	        // Clamp the verify span to the request's remaining output budget so
249	        // a long accepted run can't overshoot max_tokens.
250	        let remaining = active.max_tokens.saturating_sub(active.generated_count);
251	        // A continuing active request always has budget left (resolve emits
252	        // FinishMany the moment generated_count hits max_tokens), so
253	        // this is a true invariant, not a runtime condition — don't crash the
254	        // scheduler thread in release on a state we've proven unreachable.
255	        debug_assert!(remaining > 0, "active request must have output budget");
256	        let mut token_ids = draft.token_ids.clone();
257	        token_ids.truncate(remaining);
258	        requests.push(VerifyStepItem::new(
259	            draft.request_id,
260	            token_ids,
261	            active.params,
262	            active.stop_policy.clone(),
263	        ));
264	    }
265	    requests
266	}
267	
268	/// One-token verify spans for a gated round: each request's confirmed last
269	/// token and nothing else.
270	fn build_gated_verify_items(active: &[ActiveRequestState]) -> Vec<VerifyStepItem> {
271	    active
272	        .iter()
273	        .map(|req| {
274	            VerifyStepItem::new(
275	                req.request_id,
276	                vec![req.last_token],
277	                req.params,
278	                req.stop_policy.clone(),
279	            )
280	        })
281	        .collect()
282	}
283	
284	fn build_prefill_items(pending: &[PendingRequest], indices: &[usize]) -> Vec<PrefillStepItem> {
285	    indices
286	        .iter()
287	        .map(|&index| {
288	            let r = &pending[index];
289	            PrefillStepItem {
290	                request_id: r.request_id,
291	                prompt_tokens: r.prompt_tokens.clone(),
292	                max_output_tokens: r.max_tokens,
293	                params: r.params,
294	                logprobs: r.logprobs,
295	                prompt_logprobs: r.prompt_logprobs,
296	                lora_adapter: r.lora_adapter.clone(),
297	                // No lookup has run yet for this chunk; the executor fills it
298	                // in (`None` stays `None` when it never runs one).
299	                cached_tokens: None,
300	                external_hit_tokens: None,
301	                chunk_budget: r.step_chunk,
302	                chunk_start: 0,
303	                chunk_tokens: 0,
304	            }
305	        })
306	        .collect()
307	}
308	
309	fn build_decode_items(active: &[ActiveRequestState], indices: &[usize]) -> Vec<DecodeStepItem> {
310	    indices
311	        .iter()
312	        .map(|&index| {
313	            let r = &active[index];
314	            DecodeStepItem {
315	                request_id: r.request_id,
316	                token_id: r.last_token,
317	                params: r.params,
318	                logprobs: r.logprobs,
319	                lora_adapter: r.lora_adapter.clone(),
320	            }
321	        })
322	        .collect()
323	}
324	
325	fn sort_prefill_results(results: &mut [crate::executor::PrefillRequestResult]) {
326	    results.sort_by_key(|result| result.request_id);
327	}
328	
329	fn sort_decode_results(results: &mut [crate::executor::DecodeRequestResult]) {
330	    results.sort_by_key(|result| result.request_id);
331	}
