58	pub(crate) fn build_next_plan(
59	    have_active: bool,
60	    pending: Vec<PendingRequest>,
61	    speculative: bool,
62	) -> Option<ExecutionPlan> {
63	    // Prompt-logprobs requests need all-position logits, which the unified
64	    // forward does not compute (it passes all_position_logits=None). And under
65	    // DFlash speculation, an eligible request must capture its target hidden
66	    // context during prefill — the unified forward skips that capture, so a
67	    // request prefilled via Unified would never become draft-ready and DFlash
68	    // would silently no-op for it forever. Either way, route pending through a
69	    // dedicated prefill step instead of degrading silently.
70	    let needs_prompt_logprobs = pending.iter().any(|req| req.prompt_logprobs.is_some());
71	    // Deliberately a loose superset of the real capture eligibility
72	    // (`prefill_capture_supported`, which also needs `cached_tokens == 0 && no
73	    // prompt logprobs`): over-routing an ineligible request to a dedicated
74	    // prefill only costs one fusion, but under-routing a capture-eligible one
75	    // into Unified would silently break its readiness. Never tighten this into
76	    // the dangerous direction.
77	    let needs_dflash_capture = speculative
78	        && pending
79	            .iter()
80	            .any(|r| r.lora_adapter.is_none() && r.logprobs.is_none());
81	    if !pending.is_empty() && have_active && !needs_prompt_logprobs && !needs_dflash_capture {
82	        Some(ExecutionPlan::Unified { pending })
83	    } else if !pending.is_empty() {
84	        Some(ExecutionPlan::Prefill { pending })
85	    } else if have_active {
86	        Some(ExecutionPlan::Decode)
87	    } else {
88	        None
89	    }
90	}
