142	                gated: true,
143	            })?;
144	            verify.requests.sort_by_key(|result| result.request_id);
145	            Ok(ExecutionArtifacts::SpeculativeDecode { verify })
146	        }
147	        ExecutionPlan::Unified { pending } => {
148	            let pending_indices: Vec<usize> = (0..pending.len()).collect();
149	            let active_indices: Vec<usize> = (0..active.len()).collect();
150	            let prefill_requests = build_prefill_items(&pending, &pending_indices);
151	            let decode_requests = build_decode_items(active, &active_indices);
