164	/// `PEGAINFER_SPEC_MAX_BATCH=<n>` turns on the load-aware speculation gate: once
165	/// the active batch reaches `<n>` requests, the engine stops proposing drafts
166	/// for that step. `0`/unset = off. Read once; a malformed value refuses to
167	/// start (see [`crate::spec_env`]).
168	pub(crate) fn spec_max_batch() -> usize {
169	    static MAX_BATCH: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
170	    *MAX_BATCH.get_or_init(|| crate::spec_env::read(crate::spec_env::MAX_BATCH))
171	}
