173	/// What the engine does with the active batch this step.
174	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
175	pub(crate) enum SpeculationDecision {
176	    /// Every request is draft-ready and the batch is under the load gate:
177	    /// draft + verify.
178	    Speculate,
179	    /// Every request is draft-ready but the batch reached the load gate.
180	    Gated,
181	    /// Some request is not draft-ready, the batch is wider than the drafter
182	    /// serves, or no drafter is loaded: plain decode.
183	    NotReady,
184	}
185	
186	/// All-or-nothing: speculate the whole active batch only when every request is
187	/// draft-ready (no LoRA, no logprobs). A single non-ready request falls the
188	/// batch back to plain decode rather than running a mixed step. Sampling
189	/// params are NOT a gate: sampled-verify (#512) runs the regular sampler over
190	/// the verify rows, so the full surface — temperature/top_k/top_p/min_p/seed —
191	/// rides the speculative path.
192	pub(crate) fn speculation_decision_at(
193	    executor: &impl ModelExecutor,
194	    active: &[ActiveRequestState],
195	    max_batch: usize,
196	) -> SpeculationDecision {
197	    if !executor.speculative_enabled() || active.is_empty() {
198	        return SpeculationDecision::NotReady;
199	    }
200	    if executor
201	        .max_draft_batch()
202	        .is_some_and(|limit| active.len() > limit)
203	    {
204	        return SpeculationDecision::NotReady;
205	    }
206	    let all_ready = active.iter().all(|req| {
207	        executor.speculative_request_ready(req.request_id)
208	            && req.lora_adapter.is_none()
209	            && req.logprobs.is_none()
210	    });
211	    if !all_ready {
212	        return SpeculationDecision::NotReady;
213	    }
214	    if max_batch > 0 && active.len() >= max_batch {
215	        SpeculationDecision::Gated
216	    } else {
217	        SpeculationDecision::Speculate
218	    }
219	}
