499	            "active + pending prompt_logprobs=0 request routes to prefill not unified"
500	        );
501	        // No prompt logprobs requested → the unified fusion is fine.
502	        let plain = pending();
503	        assert!(
504	            matches!(
505	                build_next_plan(true, vec![plain], false),
506	                Some(ExecutionPlan::Unified { pending }) if pending.len() == 1
507	            ),
508	            "active + pending plain request (no prompt logprobs) can use unified"
509	        );
510	        // Under DFlash speculation, an eligible pending must capture its
511	        // target context during prefill — the unified forward skips that capture,
512	        // so route it to a dedicated prefill step rather than let DFlash silently
513	        // no-op for it.
514	        assert!(
515	            matches!(
516	                build_next_plan(true, vec![pending()], true),
517	                Some(ExecutionPlan::Prefill { pending }) if pending.len() == 1
518	            ),
519	            "spec + active + eligible pending routes to prefill so the drafter context is captured"
520	        );
521	        // Sampled-verify (#512): a non-greedy pending speculates too, so it
522	        // needs the same capture — Prefill, not Unified (which would silently
523	        // never make it draft-ready). This covers min_p and seeded params as
524	        // well; nothing on the sampling surface opts a request out.
525	        for params in [
526	            SamplingParams {
527	                temperature: 1.0,
528	                ..SamplingParams::default()
529	            },
530	            SamplingParams {
531	                temperature: 0.8,
532	                min_p: 0.05,
533	                ..SamplingParams::default()
534	            },
535	            SamplingParams {
536	                temperature: 0.8,
537	                seed: Some(42),
538	                ..SamplingParams::default()
539	            },
540	        ] {
541	            let mut sampled = pending();
542	            sampled.params = params;
543	            assert!(
544	                matches!(
545	                    build_next_plan(true, vec![sampled], true),
546	                    Some(ExecutionPlan::Prefill { pending }) if pending.len() == 1
547	                ),
548	                "spec + active + sampled pending routes to prefill for draft capture"
549	            );
550	        }
551	        // A LoRA pending never speculates, so no capture is needed and unified
552	        // fusion is still fine under speculation.
553	        let mut lora = pending();
554	        lora.lora_adapter = Some("adapter".to_string());
555	        assert!(
556	            matches!(
557	                build_next_plan(true, vec![lora], true),
558	                Some(ExecutionPlan::Unified { pending }) if pending.len() == 1
559	            ),
560	            "spec + active + LoRA pending (never speculates, no capture) can use unified"
561	        );
562	    }
563	}
