33	/// Decode-overlap prefills park until a test opens the gate; the counters let
34	/// the test wait for a launch or for scheduler steps.
35	#[derive(Default)]
36	pub(crate) struct AsyncPrefillGate {
37	    /// Synchronous prefills wait while set, so a test can queue requests behind one.
38	    pub(crate) hold_prefill: AtomicBool,
39	    /// When non-zero, `hold_prefill` holds only the synchronous prefill with
40	    /// this 1-based call number.
41	    pub(crate) hold_call: AtomicUsize,
42	    /// Synchronous prefills entered so far.
43	    pub(crate) prefill_calls: AtomicUsize,
44	    pub(crate) open: AtomicBool,
45	    pub(crate) launches: AtomicUsize,
46	    pub(crate) polls: AtomicUsize,
47	}
48	
49	#[allow(clippy::struct_excessive_bools)] // test double: independent knobs, not a state machine
50	pub(crate) struct FakeExecutor {
51	    pub(crate) block_size: usize,
52	    max_request_blocks: usize,
53	    max_context_tokens: usize,
54	    max_decode_batch_size: usize,
55	    available_blocks: usize,
56	    held_tokens: HashMap<RequestId, usize>,
57	    // Prompt progress of requests mid-chunked-prefill (mirrors the real
58	    // executor's kv_position so multi-chunk scheduling is exercised).
59	    prefill_positions: HashMap<RequestId, usize>,
60	    fail_decode_once: bool,
61	    worker_lost: bool,
62	    decode_delay: Duration,
63	    loaded_lora_adapters: HashSet<String>,
64	    pub(crate) dropped: Arc<Mutex<Vec<u64>>>,
65	    pub(crate) prefetch_offers: Arc<Mutex<Vec<u64>>>,
66	    stop_token: Option<u32>,
67	    emit_logprobs: bool,
68	    /// Whether a draft model is loaded (the fake reports every request as
69	    /// draft-ready unless it is listed in `not_ready`).
70	    speculative: bool,
71	    /// Requests the fake reports as NOT having captured draft context.
72	    not_ready: HashSet<RequestId>,
73	    max_draft_batch: Option<usize>,
74	    async_prefill: Option<Arc<AsyncPrefillGate>>,
75	    parked_prefill: Option<PrefillResult>,
76	    // `cached_tokens` the first prefill chunk of every request reports (a
77	    // simulated prefix-cache lookup). Drives the prefix-cache query/hit
78	    // counters without a real GPU KV cache. `None` models a real executor with
79	    // prefix caching switched off, which never calls `match_and_add_prefix`
80	    // and must therefore report no queries.
81	    prefix_hit_tokens: Option<usize>,
82	    // Tokens of the simulated hit attributed to the external side (CPU offload
83	    // / P2P) rather than found in local KV. `None` models an engine that
84	    // consulted no connector for this request, so the external family stays
85	    // unreported; `Some(0)` is a probe that restored nothing.
86	    prefix_external_hit_tokens: Option<usize>,
87	    connector_lookups: ConnectorLookupCounters,
88	}
89	
90	impl FakeExecutor {
91	    pub(crate) fn new(max_request_blocks: usize, dropped: Arc<Mutex<Vec<u64>>>) -> Self {
92	        Self {
93	            block_size: 16,
94	            max_request_blocks,
95	            max_context_tokens: usize::MAX,
96	            max_decode_batch_size: 64,
97	            available_blocks: max_request_blocks,
98	            held_tokens: HashMap::new(),
99	            prefill_positions: HashMap::new(),
100	            fail_decode_once: false,
101	            worker_lost: false,
102	            decode_delay: Duration::ZERO,
103	            loaded_lora_adapters: HashSet::new(),
104	            dropped,
105	            prefetch_offers: Arc::new(Mutex::new(Vec::new())),
106	            stop_token: None,
107	            emit_logprobs: false,
108	            speculative: false,
109	            not_ready: HashSet::new(),
110	            max_draft_batch: None,
111	            async_prefill: None,
112	            parked_prefill: None,
113	            prefix_hit_tokens: Some(0),
114	            prefix_external_hit_tokens: None,
115	            connector_lookups: ConnectorLookupCounters::default(),
116	        }
117	    }
118	
119	    pub(crate) fn with_max_decode_batch_size(mut self, slots: usize) -> Self {
120	        self.max_decode_batch_size = slots;
121	        self
122	    }
123	
124	    pub(crate) fn with_async_prefill(mut self, gate: Arc<AsyncPrefillGate>) -> Self {
125	        self.async_prefill = Some(gate);
126	        self
127	    }
128	
129	    /// Simulate a prefix-cache hit on every request's first prefill chunk by
130	    /// reporting `tokens` cached tokens.
131	    pub(crate) fn with_prefix_hit(mut self, tokens: usize) -> Self {
132	        self.prefix_hit_tokens = Some(tokens);
133	        self
134	    }
135	
136	    /// Model an executor that never consults a prefix cache (caching switched
137	    /// off): no `match_and_add_prefix` happens, so no query may be counted.
138	    pub(crate) fn without_prefix_cache(mut self) -> Self {
139	        self.prefix_hit_tokens = None;
140	        self
141	    }
142	
143	    /// Simulate a connector that was consulted for every request and restored
144	    /// `tokens` externally. Without this the external family reports nothing.
145	    pub(crate) fn with_external_prefix_hit(mut self, tokens: usize) -> Self {
146	        self.prefix_external_hit_tokens = Some(tokens);
147	        self
148	    }
149	
150	    pub(crate) fn with_stop_token(mut self, token: u32) -> Self {
151	        self.stop_token = Some(token);
152	        self
153	    }
154	
155	    pub(crate) fn with_logprobs(mut self) -> Self {
156	        self.emit_logprobs = true;
157	        self
158	    }
159	
160	    pub(crate) fn with_decode_failure(mut self) -> Self {
161	        self.fail_decode_once = true;
162	        self
163	    }
164	
165	    /// Decode fails the way the real executor does once a rank worker is gone.
166	    pub(crate) fn with_worker_lost(mut self) -> Self {
167	        self.worker_lost = true;
168	        self
169	    }
170	
171	    pub(crate) fn with_decode_delay(mut self, delay: Duration) -> Self {
172	        self.decode_delay = delay;
173	        self
174	    }
175	
176	    pub(crate) fn with_lora_adapters(mut self, names: &[&str]) -> Self {
177	        self.loaded_lora_adapters = names.iter().map(|name| (*name).to_string()).collect();
178	        self
179	    }
180	
181	    /// Pretend a draft model is loaded: every request reports captured draft
182	    /// context unless it is named in [`Self::with_request_not_ready`].
183	    pub(crate) fn with_speculative(mut self) -> Self {
184	        self.speculative = true;
185	        self
186	    }
187	
188	    /// Report one request as NOT draft-ready (no captured draft context).
189	    pub(crate) fn with_request_not_ready(mut self, request_id: RequestId) -> Self {
190	        self.not_ready.insert(request_id);
191	        self
192	    }
193	
194	    pub(crate) fn with_max_draft_batch(mut self, limit: usize) -> Self {
195	        self.max_draft_batch = Some(limit);
196	        self
197	    }
198	
199	    /// Advance a request's prompt by one chunk, mirroring the real
200	    /// executor: clamp the scheduler's budget to the tokens remaining
201	    /// and report the new authoritative position.
202	    fn fake_prefill_result(&mut self, req: &PrefillStepItem) -> PrefillRequestResult {
203	        let start = self
204	            .prefill_positions
205	            .get(&req.request_id)
206	            .copied()
207	            .unwrap_or(0);
208	        let chunk = (req.prompt_tokens.len() - start).min(req.chunk_budget);
209	        let prefill_pos = start + chunk;
210	        let completed = prefill_pos == req.prompt_tokens.len();
211	        if completed {
212	            self.prefill_positions.remove(&req.request_id);
213	        } else {
214	            self.prefill_positions.insert(req.request_id, prefill_pos);
215	        }
216	        // The external family is only reported for a request whose connector
217	        // was consulted; later chunks contribute nothing.
218	        let external_hit_tokens = if start == 0 && self.prefix_hit_tokens.is_some() {
219	            self.prefix_external_hit_tokens
220	        } else {
221	            None
222	        };
223	        // Mirror the real executor's settle point: the connector is asked
224	        // about whatever was not already local, once per request.
225	        if let Some((hit, external)) = self.prefix_hit_tokens.zip(external_hit_tokens) {
226	            self.connector_lookups.queries +=
227	                (req.prompt_tokens.len() - hit.saturating_sub(external)) as u64;
228	            self.connector_lookups.hits += external as u64;
229	        }
230	        PrefillRequestResult {
231	            request_id: req.request_id,
232	            first_token: 100 + req.request_id.raw() as u32,
233	            first_token_logprob: self.emit_logprobs.then(|| {
234	                let token = 100 + req.request_id.raw() as u32;
235	                pegainfer_frontend::engine::TokenLogprob {
236	                    logprob: -0.1,
237	                    rank: 0,
238	                    top_logprobs: vec![(token, -0.1)],
239	                }
240	            }),
241	            prompt_logprobs: None,
242	            // A simulated lookup is reported only on the request's first chunk
243	            // (start == 0); later chunks carry no cached prefix. `None` models
244	            // a cache that never ran a lookup (switched off, or prompt
245	            // scoring).
246	            cached_tokens: if start == 0 {
247	                self.prefix_hit_tokens
248	            } else {
249	                None
250	            },
251	            external_hit_tokens,
252	            completed,
253	            prefill_pos,
254	        }
255	    }
256	
257	    /// The real executor panics past its largest decode graph bucket.
258	    fn check_decode_batch(&self, rows: usize) -> Result<()> {
259	        anyhow::ensure!(
260	            rows <= self.max_decode_batch_size,
261	            "fake decode batch {rows} exceeds {} slots",
262	            self.max_decode_batch_size
263	        );
264	        Ok(())
265	    }
266	
267	    pub(crate) fn ensure_request_tokens(
268	        &mut self,
269	        request_id: RequestId,
270	        token_count: usize,
271	    ) -> Result<()> {
272	        let current_tokens = self.held_tokens.get(&request_id).copied().unwrap_or(0);
273	        let current_blocks = blocks_needed(current_tokens, self.block_size);
274	        let needed_blocks = blocks_needed(token_count, self.block_size);
275	        let grow = needed_blocks.saturating_sub(current_blocks);
276	        if grow > self.available_blocks {
277	            anyhow::bail!("fake KV capacity exhausted");
278	        }
279	        self.available_blocks -= grow;
280	        self.held_tokens.insert(request_id, token_count);
281	        Ok(())
282	    }
283	}
284	
285	impl ModelExecutor for FakeExecutor {
286	    fn block_size(&self) -> usize {
287	        self.block_size
288	    }
289	
290	    fn max_request_blocks(&self) -> usize {
291	        self.max_request_blocks
292	    }
293	
294	    fn max_context_tokens(&self) -> usize {
295	        self.max_context_tokens
296	    }
297	
298	    fn max_decode_batch_size(&self) -> usize {
299	        self.max_decode_batch_size
300	    }
301	
302	    fn available_blocks(&self) -> usize {
303	        self.available_blocks
304	    }
305	
306	    fn is_stop_token(&self, token_id: u32) -> bool {
307	        self.stop_token == Some(token_id)
308	    }
309	
310	    fn speculative_enabled(&self) -> bool {
311	        self.speculative
312	    }
313	
314	    fn speculative_request_ready(&self, request_id: RequestId) -> bool {
315	        self.speculative && !self.not_ready.contains(&request_id)
316	    }
317	
318	    fn max_draft_batch(&self) -> Option<usize> {
319	        self.max_draft_batch
320	    }
321	
322	    fn connector_lookup_counters(&self) -> ConnectorLookupCounters {
323	        self.connector_lookups
324	    }
325	
326	    fn drop_request(&mut self, request_id: RequestId) -> Result<()> {
327	        if let Some(tokens) = self.held_tokens.remove(&request_id) {
328	            self.available_blocks += blocks_needed(tokens, self.block_size);
329	        }
330	        self.prefill_positions.remove(&request_id);
331	        self.dropped.lock().unwrap().push(request_id.raw());
332	        Ok(())
333	    }
334	
335	    fn begin_kv_prefetch(
336	        &mut self,
337	        request_id: RequestId,
338	        _prompt_tokens: &[u32],
339	        _lora_adapter: Option<&str>,
340	        _reserve_floor: usize,
341	    ) -> bool {
342	        self.prefetch_offers.lock().unwrap().push(request_id.raw());
343	        false
344	    }
345	
346	    fn list_lora_adapters(&self) -> Vec<String> {
347	        let mut names: Vec<_> = self.loaded_lora_adapters.iter().cloned().collect();
348	        names.sort();
349	        names
350	    }
351	
352	    fn unload_lora_adapter(&mut self, request: &UnloadLoraAdapterRequest) -> Result<()> {
353	        anyhow::ensure!(
354	            self.loaded_lora_adapters.remove(&request.lora_name),
355	            "LoRA adapter is not loaded: {}",
356	            request.lora_name
357	        );
358	        Ok(())
359	    }
360	
361	    fn execute_prefill(&mut self, plan: PrefillPlan<'_>) -> Result<PrefillResult> {
362	        if let Some(gate) = &self.async_prefill {
363	            let call = gate.prefill_calls.fetch_add(1, Ordering::SeqCst) + 1;
364	            let held = || {
365	                let only = gate.hold_call.load(Ordering::SeqCst);
366	                gate.hold_prefill.load(Ordering::SeqCst) && (only == 0 || only == call)
367	            };
368	            let start = Instant::now();
369	            while held() {
370	                assert!(
371	                    start.elapsed() < Duration::from_secs(10),
372	                    "fake prefill held"
373	                );
374	                std::thread::sleep(Duration::from_millis(1));
375	            }
376	        }
377	        for req in plan.requests {
378	            self.ensure_request_tokens(req.request_id, req.prompt_tokens.len())?;
379	        }
380	        Ok(PrefillResult {
381	            requests: plan
382	                .requests
383	                .iter()
384	                .map(|req| self.fake_prefill_result(req))
385	                .collect(),
386	            draft_context_captured_requests: Vec::new(),
387	        })
388	    }
389	
390	    fn execute_decode(&mut self, plan: DecodePlan<'_>) -> Result<crate::executor::DecodeResult> {
391	        if !self.decode_delay.is_zero() {
392	            std::thread::sleep(self.decode_delay);
393	        }
394	        if self.fail_decode_once {
395	            self.fail_decode_once = false;
396	            anyhow::bail!("fake decode KV capacity exhausted");
397	        }
398	        if self.worker_lost {
399	            return Err(crate::executor::worker_lost("fake rank worker exited"));
400	        }
401	        self.check_decode_batch(plan.requests.len())?;
402	
403	        for req in plan.requests {
404	            let current_tokens = self
405	                .held_tokens
406	                .get(&req.request_id)
407	                .copied()
408	                .ok_or_else(|| anyhow::anyhow!("missing fake request state"))?;
