//! Shared fakes for the scheduler mechanics tests and the frontend-adapter
//! contract tests.

use std::collections::HashMap;
use std::collections::HashSet;
use std::sync::Arc;
use std::sync::Mutex;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::AtomicUsize;
use std::sync::atomic::Ordering;
use std::time::Duration;
use std::time::Instant;

use anyhow::Result;
use pegainfer_frontend::engine::Request;
use pegainfer_frontend::engine::StopPolicy;
use pegainfer_frontend::engine::UnloadLoraAdapterRequest;
use pegainfer_frontend::sampler::SamplingParams;

use super::blocks_needed;
use crate::executor::ConnectorLookupCounters;
use crate::executor::DecodePlan;
use crate::executor::DecodeRequestResult;
use crate::executor::ModelExecutor;
use crate::executor::PrefillPlan;
use crate::executor::PrefillRequestResult;
use crate::executor::PrefillResult;
use crate::executor::PrefillStepItem;
use crate::executor::RequestId;
use crate::executor::UnifiedPlan;
use crate::executor::UnifiedResult;

/// Decode-overlap prefills park until a test opens the gate; the counters let
/// the test wait for a launch or for scheduler steps.
#[derive(Default)]
pub(crate) struct AsyncPrefillGate {
    /// Synchronous prefills wait while set, so a test can queue requests behind one.
    pub(crate) hold_prefill: AtomicBool,
    /// When non-zero, `hold_prefill` holds only the synchronous prefill with
    /// this 1-based call number.
    pub(crate) hold_call: AtomicUsize,
    /// Synchronous prefills entered so far.
    pub(crate) prefill_calls: AtomicUsize,
    pub(crate) open: AtomicBool,
    pub(crate) launches: AtomicUsize,
    pub(crate) polls: AtomicUsize,
}

#[allow(clippy::struct_excessive_bools)] // test double: independent knobs, not a state machine
pub(crate) struct FakeExecutor {
    pub(crate) block_size: usize,
    max_request_blocks: usize,
    max_context_tokens: usize,
    max_decode_batch_size: usize,
    available_blocks: usize,
    held_tokens: HashMap<RequestId, usize>,
    // Prompt progress of requests mid-chunked-prefill (mirrors the real
    // executor's kv_position so multi-chunk scheduling is exercised).
    prefill_positions: HashMap<RequestId, usize>,
    fail_decode_once: bool,
    worker_lost: bool,
    decode_delay: Duration,
    loaded_lora_adapters: HashSet<String>,
    pub(crate) dropped: Arc<Mutex<Vec<u64>>>,
    pub(crate) prefetch_offers: Arc<Mutex<Vec<u64>>>,
    stop_token: Option<u32>,
    emit_logprobs: bool,
    /// Whether a draft model is loaded (the fake reports every request as
    /// draft-ready unless it is listed in `not_ready`).
    speculative: bool,
    /// Requests the fake reports as NOT having captured draft context.
    not_ready: HashSet<RequestId>,
    max_draft_batch: Option<usize>,
    async_prefill: Option<Arc<AsyncPrefillGate>>,
    parked_prefill: Option<PrefillResult>,
    // `cached_tokens` the first prefill chunk of every request reports (a
    // simulated prefix-cache lookup). Drives the prefix-cache query/hit
    // counters without a real GPU KV cache. `None` models a real executor with
    // prefix caching switched off, which never calls `match_and_add_prefix`
    // and must therefore report no queries.
    prefix_hit_tokens: Option<usize>,
    // Tokens of the simulated hit attributed to the external side (CPU offload
    // / P2P) rather than found in local KV. `None` models an engine that
    // consulted no connector for this request, so the external family stays
    // unreported; `Some(0)` is a probe that restored nothing.
    prefix_external_hit_tokens: Option<usize>,
    connector_lookups: ConnectorLookupCounters,
}

impl FakeExecutor {
    pub(crate) fn new(max_request_blocks: usize, dropped: Arc<Mutex<Vec<u64>>>) -> Self {
        Self {
            block_size: 16,
            max_request_blocks,
            max_context_tokens: usize::MAX,
            max_decode_batch_size: 64,
            available_blocks: max_request_blocks,
            held_tokens: HashMap::new(),
            prefill_positions: HashMap::new(),
            fail_decode_once: false,
            worker_lost: false,
            decode_delay: Duration::ZERO,
            loaded_lora_adapters: HashSet::new(),
            dropped,
            prefetch_offers: Arc::new(Mutex::new(Vec::new())),
            stop_token: None,
            emit_logprobs: false,
            speculative: false,
            not_ready: HashSet::new(),
            max_draft_batch: None,
            async_prefill: None,
            parked_prefill: None,
            prefix_hit_tokens: Some(0),
            prefix_external_hit_tokens: None,
            connector_lookups: ConnectorLookupCounters::default(),
        }
    }

    pub(crate) fn with_max_decode_batch_size(mut self, slots: usize) -> Self {
        self.max_decode_batch_size = slots;
        self
    }

    pub(crate) fn with_async_prefill(mut self, gate: Arc<AsyncPrefillGate>) -> Self {
        self.async_prefill = Some(gate);
        self
    }

    /// Simulate a prefix-cache hit on every request's first prefill chunk by
    /// reporting `tokens` cached tokens.
    pub(crate) fn with_prefix_hit(mut self, tokens: usize) -> Self {
        self.prefix_hit_tokens = Some(tokens);
        self
    }

    /// Model an executor that never consults a prefix cache (caching switched
    /// off): no `match_and_add_prefix` happens, so no query may be counted.
    pub(crate) fn without_prefix_cache(mut self) -> Self {
        self.prefix_hit_tokens = None;
        self
    }

    /// Simulate a connector that was consulted for every request and restored
    /// `tokens` externally. Without this the external family reports nothing.
    pub(crate) fn with_external_prefix_hit(mut self, tokens: usize) -> Self {
        self.prefix_external_hit_tokens = Some(tokens);
        self
    }

    pub(crate) fn with_stop_token(mut self, token: u32) -> Self {
        self.stop_token = Some(token);
        self
    }

    pub(crate) fn with_logprobs(mut self) -> Self {
        self.emit_logprobs = true;
        self
    }

    pub(crate) fn with_decode_failure(mut self) -> Self {
        self.fail_decode_once = true;
        self
    }

    /// Decode fails the way the real executor does once a rank worker is gone.
    pub(crate) fn with_worker_lost(mut self) -> Self {
        self.worker_lost = true;
        self
    }

    pub(crate) fn with_decode_delay(mut self, delay: Duration) -> Self {
        self.decode_delay = delay;
        self
    }

    pub(crate) fn with_lora_adapters(mut self, names: &[&str]) -> Self {
        self.loaded_lora_adapters = names.iter().map(|name| (*name).to_string()).collect();
        self
    }

    /// Pretend a draft model is loaded: every request reports captured draft
    /// context unless it is named in [`Self::with_request_not_ready`].
    pub(crate) fn with_speculative(mut self) -> Self {
        self.speculative = true;
        self
    }

    /// Report one request as NOT draft-ready (no captured draft context).
    pub(crate) fn with_request_not_ready(mut self, request_id: RequestId) -> Self {
        self.not_ready.insert(request_id);
        self
    }

    pub(crate) fn with_max_draft_batch(mut self, limit: usize) -> Self {
        self.max_draft_batch = Some(limit);
        self
    }

    /// Advance a request's prompt by one chunk, mirroring the real
    /// executor: clamp the scheduler's budget to the tokens remaining
    /// and report the new authoritative position.
    fn fake_prefill_result(&mut self, req: &PrefillStepItem) -> PrefillRequestResult {
        let start = self
            .prefill_positions
            .get(&req.request_id)
            .copied()
            .unwrap_or(0);
        let chunk = (req.prompt_tokens.len() - start).min(req.chunk_budget);
        let prefill_pos = start + chunk;
        let completed = prefill_pos == req.prompt_tokens.len();
        if completed {
            self.prefill_positions.remove(&req.request_id);
        } else {
            self.prefill_positions.insert(req.request_id, prefill_pos);
        }
        // The external family is only reported for a request whose connector
        // was consulted; later chunks contribute nothing.
        let external_hit_tokens = if start == 0 && self.prefix_hit_tokens.is_some() {
            self.prefix_external_hit_tokens
        } else {
            None
        };
        // Mirror the real executor's settle point: the connector is asked
        // about whatever was not already local, once per request.
        if let Some((hit, external)) = self.prefix_hit_tokens.zip(external_hit_tokens) {
            self.connector_lookups.queries +=
                (req.prompt_tokens.len() - hit.saturating_sub(external)) as u64;
            self.connector_lookups.hits += external as u64;
        }
        PrefillRequestResult {
            request_id: req.request_id,
            first_token: 100 + req.request_id.raw() as u32,
            first_token_logprob: self.emit_logprobs.then(|| {
                let token = 100 + req.request_id.raw() as u32;
                pegainfer_frontend::engine::TokenLogprob {
                    logprob: -0.1,
                    rank: 0,
                    top_logprobs: vec![(token, -0.1)],
                }
            }),
            prompt_logprobs: None,
            // A simulated lookup is reported only on the request's first chunk
            // (start == 0); later chunks carry no cached prefix. `None` models
            // a cache that never ran a lookup (switched off, or prompt
            // scoring).
            cached_tokens: if start == 0 {
                self.prefix_hit_tokens
            } else {
                None
            },
            external_hit_tokens,
            completed,
            prefill_pos,
        }
    }

    /// The real executor panics past its largest decode graph bucket.
    fn check_decode_batch(&self, rows: usize) -> Result<()> {
        anyhow::ensure!(
            rows <= self.max_decode_batch_size,
            "fake decode batch {rows} exceeds {} slots",
            self.max_decode_batch_size
        );
        Ok(())
    }

    pub(crate) fn ensure_request_tokens(
        &mut self,
        request_id: RequestId,
        token_count: usize,
    ) -> Result<()> {
        let current_tokens = self.held_tokens.get(&request_id).copied().unwrap_or(0);
        let current_blocks = blocks_needed(current_tokens, self.block_size);
        let needed_blocks = blocks_needed(token_count, self.block_size);
        let grow = needed_blocks.saturating_sub(current_blocks);
        if grow > self.available_blocks {
            anyhow::bail!("fake KV capacity exhausted");
        }
        self.available_blocks -= grow;
        self.held_tokens.insert(request_id, token_count);
        Ok(())
    }
}

impl ModelExecutor for FakeExecutor {
    fn block_size(&self) -> usize {
        self.block_size
    }

    fn max_request_blocks(&self) -> usize {
        self.max_request_blocks
    }

    fn max_context_tokens(&self) -> usize {
        self.max_context_tokens
    }

    fn max_decode_batch_size(&self) -> usize {
        self.max_decode_batch_size
    }

    fn available_blocks(&self) -> usize {
        self.available_blocks
    }

    fn is_stop_token(&self, token_id: u32) -> bool {
        self.stop_token == Some(token_id)
    }

    fn speculative_enabled(&self) -> bool {
        self.speculative
    }

    fn speculative_request_ready(&self, request_id: RequestId) -> bool {
        self.speculative && !self.not_ready.contains(&request_id)
    }

    fn max_draft_batch(&self) -> Option<usize> {
        self.max_draft_batch
    }

    fn connector_lookup_counters(&self) -> ConnectorLookupCounters {
        self.connector_lookups
    }

    fn drop_request(&mut self, request_id: RequestId) -> Result<()> {
        if let Some(tokens) = self.held_tokens.remove(&request_id) {
            self.available_blocks += blocks_needed(tokens, self.block_size);
        }
        self.prefill_positions.remove(&request_id);
        self.dropped.lock().unwrap().push(request_id.raw());
        Ok(())
    }

    fn begin_kv_prefetch(
        &mut self,
        request_id: RequestId,
        _prompt_tokens: &[u32],
        _lora_adapter: Option<&str>,
        _reserve_floor: usize,
    ) -> bool {
        self.prefetch_offers.lock().unwrap().push(request_id.raw());
        false
    }

    fn list_lora_adapters(&self) -> Vec<String> {
        let mut names: Vec<_> = self.loaded_lora_adapters.iter().cloned().collect();
        names.sort();
        names
    }

    fn unload_lora_adapter(&mut self, request: &UnloadLoraAdapterRequest) -> Result<()> {
        anyhow::ensure!(
            self.loaded_lora_adapters.remove(&request.lora_name),
            "LoRA adapter is not loaded: {}",
            request.lora_name
        );
        Ok(())
    }

    fn execute_prefill(&mut self, plan: PrefillPlan<'_>) -> Result<PrefillResult> {
        if let Some(gate) = &self.async_prefill {
            let call = gate.prefill_calls.fetch_add(1, Ordering::SeqCst) + 1;
            let held = || {
                let only = gate.hold_call.load(Ordering::SeqCst);
                gate.hold_prefill.load(Ordering::SeqCst) && (only == 0 || only == call)
            };
            let start = Instant::now();
            while held() {
                assert!(
                    start.elapsed() < Duration::from_secs(10),
                    "fake prefill held"
                );
                std::thread::sleep(Duration::from_millis(1));
            }
        }
        for req in plan.requests {
            self.ensure_request_tokens(req.request_id, req.prompt_tokens.len())?;
        }
        Ok(PrefillResult {
            requests: plan
                .requests
                .iter()
                .map(|req| self.fake_prefill_result(req))
                .collect(),
            draft_context_captured_requests: Vec::new(),
        })
    }

    fn execute_decode(&mut self, plan: DecodePlan<'_>) -> Result<crate::executor::DecodeResult> {
        if !self.decode_delay.is_zero() {
            std::thread::sleep(self.decode_delay);
        }
        if self.fail_decode_once {
            self.fail_decode_once = false;
            anyhow::bail!("fake decode KV capacity exhausted");
        }
        if self.worker_lost {
            return Err(crate::executor::worker_lost("fake rank worker exited"));
        }
        self.check_decode_batch(plan.requests.len())?;

        for req in plan.requests {
            let current_tokens = self
                .held_tokens
                .get(&req.request_id)
                .copied()
                .ok_or_else(|| anyhow::anyhow!("missing fake request state"))?;
            self.ensure_request_tokens(req.request_id, current_tokens + 1)?;
        }

        Ok(crate::executor::DecodeResult {
            requests: plan
                .requests
                .iter()
                .map(|req| DecodeRequestResult {
                    request_id: req.request_id,
                    token: 200 + req.request_id.raw() as u32,
                    logprob: self.emit_logprobs.then(|| {
                        let token = 200 + req.request_id.raw() as u32;
                        pegainfer_frontend::engine::TokenLogprob {
                            logprob: -0.2,
                            rank: 0,
                            top_logprobs: vec![(token, -0.2)],
                        }
                    }),
                })
                .collect(),
        })
    }

    fn execute_unified(&mut self, plan: UnifiedPlan<'_>) -> Result<UnifiedResult> {
        self.check_decode_batch(plan.decode_requests.len())?;
        for req in plan.prefill_requests {
            self.ensure_request_tokens(req.request_id, req.prompt_tokens.len())?;
        }
        for req in plan.decode_requests {
            let current_tokens = self
                .held_tokens
                .get(&req.request_id)
                .copied()
                .ok_or_else(|| anyhow::anyhow!("missing fake request state"))?;
            self.ensure_request_tokens(req.request_id, current_tokens + 1)?;
        }

        let mut prefill_requests: Vec<_> = plan
            .prefill_requests
            .iter()
            .map(|req| self.fake_prefill_result(req))
            .collect();
        if let Some(gate) = &self.async_prefill {
            self.parked_prefill = Some(PrefillResult {
                requests: std::mem::take(&mut prefill_requests),
                draft_context_captured_requests: Vec::new(),
            });
            gate.launches.fetch_add(1, Ordering::SeqCst);
        }

        Ok(UnifiedResult {
            prefill_requests,
            decode_requests: plan
                .decode_requests
                .iter()
                .map(|req| DecodeRequestResult {
                    request_id: req.request_id,
                    token: 200 + req.request_id.raw() as u32,
                    logprob: None,
                })
                .collect(),
        })
    }

    fn has_decode_overlap(&self) -> bool {
        self.async_prefill.is_some()
    }

    fn poll_async_prefill(&mut self) -> Option<PrefillResult> {
        let gate = self.async_prefill.as_ref()?;
        gate.polls.fetch_add(1, Ordering::SeqCst);
        if gate.open.load(Ordering::SeqCst) {
            self.parked_prefill.take()
        } else {
            None
        }
    }
}

/// A minimal contract request: `prompt_len` filler tokens, default sampling.
pub(crate) fn request(prompt_len: usize, max_tokens: usize) -> Request {
    Request {
        prompt_tokens: vec![1; prompt_len],
        params: SamplingParams::default(),
        history_tokens: None,
        history_marks: Vec::new(),
        stop_policy: StopPolicy::default(),
        max_tokens,
        lora_adapter: None,
        kv_transfer_params: None,
        logprobs: None,
        prompt_logprobs: None,
        trace_parent: None,
        client_label: None,
    }
}

pub(crate) fn request_with_lora(
    prompt_len: usize,
    max_tokens: usize,
    lora_adapter: Option<&str>,
) -> Request {
    Request {
        lora_adapter: lora_adapter.map(ToString::to_string),
        ..request(prompt_len, max_tokens)
    }
}

