1	//! `PEGAINFER_SPEC_*` environment knobs.
2	//!
3	//! Both knobs are read once per process. A malformed value is rejected when the
4	//! engine starts, with the variable's name; unset, blank and an explicit `0`
5	//! all mean off. Silently falling back to off on a typo would turn a load lever
6	//! into a no-op that looks armed.
7	
8	use anyhow::Result;
9	use anyhow::bail;
10	
11	pub(crate) const MAX_BATCH: &str = "PEGAINFER_SPEC_MAX_BATCH";
12	pub(crate) const MAX_DRAFTS: &str = "PEGAINFER_SPEC_MAX_DRAFTS";
13	
14	/// Parse one knob: unset/blank = off (`0`), otherwise a non-negative integer.
15	fn parse(name: &str, value: Option<&str>) -> Result<usize> {
16	    let Some(raw) = value else {
17	        return Ok(0);
18	    };
19	    let trimmed = raw.trim();
20	    if trimmed.is_empty() {
21	        return Ok(0);
22	    }
23	    match trimmed.parse::<usize>() {
24	        Ok(value) => Ok(value),
25	        Err(_) => bail!("{name}: expected a non-negative integer, got {raw:?}"),
26	    }
27	}
28	
29	fn env_value(name: &str) -> Result<Option<String>> {
30	    match std::env::var(name) {
31	        Ok(value) => Ok(Some(value)),
32	        Err(std::env::VarError::NotPresent) => Ok(None),
33	        Err(std::env::VarError::NotUnicode(_)) => bail!("{name}: value is not UTF-8"),
34	    }
35	}
36	
37	/// Every engine start runs [`validate`] first, so a failure here is a broken
38	/// invariant rather than user input.
39	pub(crate) fn read(name: &str) -> usize {
40	    env_value(name)
41	        .and_then(|value| parse(name, value.as_deref()))
42	        .expect("spec knobs are validated before the engine starts")
43	}
44	
45	/// Reject malformed knob values before the engine starts.
46	pub(crate) fn validate() -> Result<()> {
47	    for name in [MAX_BATCH, MAX_DRAFTS] {
48	        parse(name, env_value(name)?.as_deref())?;
49	    }
50	    Ok(())
51	}
52	
53	#[cfg(test)]
54	mod tests {
55	    use super::*;
56	
57	    #[test]
58	    fn blank_means_off_and_a_bad_value_names_the_knob() {
59	        for off in [None, Some(""), Some("  "), Some("0")] {
60	            assert_eq!(parse(MAX_BATCH, off).unwrap(), 0);
61	        }
62	        let error = parse(MAX_DRAFTS, Some("4x")).unwrap_err().to_string();
63	        assert!(error.contains(MAX_DRAFTS), "{error}");
64	    }
65	}
66

1	//! Shared fakes for the scheduler mechanics tests and the frontend-adapter
2	//! contract tests.
