199	    /// Advance a request's prompt by one chunk, mirroring the real
200	    /// executor: clamp the scheduler's budget to the tokens remaining
201	    /// and report the new authoritative position.
202	    fn fake_prefill_result(&mut self, req: &PrefillStepItem) -> PrefillRequestResult {
203	        let start = self
204	            .prefill_positions
205	            .get(&req.request_id)
206	            .copied()
207	            .unwrap_or(0);
208	        let chunk = (req.prompt_tokens.len() - start).min(req.chunk_budget);
209	        let prefill_pos = start + chunk;
210	        let completed = prefill_pos == req.prompt_tokens.len();
211	        if completed {
212	            self.prefill_positions.remove(&req.request_id);
213	        } else {
214	            self.prefill_positions.insert(req.request_id, prefill_pos);
215	        }
216	        // The external family is only reported for a request whose connector
217	        // was consulted; later chunks contribute nothing.
218	        let external_hit_tokens = if start == 0 && self.prefix_hit_tokens.is_some() {
219	            self.prefix_external_hit_tokens
220	        } else {
221	            None
222	        };
223	        // Mirror the real executor's settle point: the connector is asked
224	        // about whatever was not already local, once per request.
225	        if let Some((hit, external)) = self.prefix_hit_tokens.zip(external_hit_tokens) {
226	            self.connector_lookups.queries +=
227	                (req.prompt_tokens.len() - hit.saturating_sub(external)) as u64;
228	            self.connector_lookups.hits += external as u64;
229	        }
230	        PrefillRequestResult {
231	            request_id: req.request_id,
232	            first_token: 100 + req.request_id.raw() as u32,
233	            first_token_logprob: self.emit_logprobs.then(|| {
234	                let token = 100 + req.request_id.raw() as u32;
235	                pegainfer_frontend::engine::TokenLogprob {
236	                    logprob: -0.1,
237	                    rank: 0,
238	                    top_logprobs: vec![(token, -0.1)],
239	                }
240	            }),
241	            prompt_logprobs: None,
242	            // A simulated lookup is reported only on the request's first chunk
243	            // (start == 0); later chunks carry no cached prefix. `None` models
244	            // a cache that never ran a lookup (switched off, or prompt
245	            // scoring).
246	            cached_tokens: if start == 0 {
247	                self.prefix_hit_tokens
248	            } else {
249	                None
250	            },
251	            external_hit_tokens,
252	            completed,
253	            prefill_pos,
254	        }
255	    }
