257	    /// The real executor panics past its largest decode graph bucket.
258	    fn check_decode_batch(&self, rows: usize) -> Result<()> {
259	        anyhow::ensure!(
260	            rows <= self.max_decode_batch_size,
261	            "fake decode batch {rows} exceeds {} slots",
262	            self.max_decode_batch_size
263	        );
264	        Ok(())
265	    }
266	
267	    pub(crate) fn ensure_request_tokens(
268	        &mut self,
269	        request_id: RequestId,
270	        token_count: usize,
271	    ) -> Result<()> {
272	        let current_tokens = self.held_tokens.get(&request_id).copied().unwrap_or(0);
273	        let current_blocks = blocks_needed(current_tokens, self.block_size);
274	        let needed_blocks = blocks_needed(token_count, self.block_size);
275	        let grow = needed_blocks.saturating_sub(current_blocks);
276	        if grow > self.available_blocks {
277	            anyhow::bail!("fake KV capacity exhausted");
278	        }
279	        self.available_blocks -= grow;
280	        self.held_tokens.insert(request_id, token_count);
281	        Ok(())
282	    }
283	}
